const d = n => new Date(Date.now() - n*86400000).toISOString().slice(0,10);
const daysSince = s => Math.floor((Date.now() - new Date(s).getTime())/86400000);
return $input.all().map(({json}) => {
 const months = Math.floor(daysSince(json.last_checkup) / 30);
 const due = months >= 6 && !json.has_future_booking && json.contact_ok;
 const reason = !json.contact_ok ? 'no consent to be contacted' : json.has_future_booking ? 'already booked' : months < 6 ? 'not due yet' : `${months} months since last checkup`;
 return {json: {...json, months_since_checkup: months, needs_action: due, reason}};
});

return $input.all().map(({json}) => {
 const first = json.name.split(' ')[0];
 const message = `Hi ${first}, it has been ${json.months_since_checkup} months since your last checkup at Maple Street Dental. You can pick a time here: https://example.com/book or reply with a day that suits you. This message was prepared by an automated assistant.`;
 return {json: {...json, channel:'email', to: json.email, subject:'Time for your checkup', message, approval:'auto_send'}};
});
